import 'package:dartz/dartz.dart'; import 'package:dio/dio.dart'; import 'package:accounting_software/app/core/foundation/types/api_result.dart'; import 'package:accounting_software/app/core/foundation/types/paginated_parser.dart'; import 'package:accounting_software/app/core/foundation/types/paginated_result.dart'; import 'package:accounting_software/app/core/network/api_client_interface.dart'; import 'package:accounting_software/app/core/network/postgrest_helpers.dart'; import 'package:accounting_software/app/features/catalog/genders/data/genders_endpoint.dart'; import 'package:accounting_software/app/features/catalog/genders/data/datasources/genders_remote_data_source.dart'; import 'package:accounting_software/app/features/catalog/genders/data/models/gender_model.dart'; import 'package:accounting_software/app/features/catalog/genders/domain/entity/gender_draft.dart'; import 'package:accounting_software/app/features/catalog/genders/domain/entity/gender_list_query.dart'; class GendersRemoteDataSourceImpl implements GendersRemoteDataSource { const GendersRemoteDataSourceImpl(this._api); final IApiClient _api; @override Future<ApiResult<PaginatedResult<GenderModel>>> getGenders(GenderListQuery q){final term=PostgrestValue.escapeFilter(q.search.trim());return _api.getPaginated<GenderModel>(GendersEndpoint.collection,fromJson:GenderModel.fromJson,page:q.page,limit:q.pageSize,parser:PaginatedParserPresets.supabase,queryParameters:{'select':GendersEndpoint.select,'order':_order(q),if(term.isNotEmpty)'or':'(name.ilike."*$term*",code.ilike."*$term*")',if(q.status==GenderStatusFilter.active)'is_active':'eq.true',if(q.status==GenderStatusFilter.inactive)'is_active':'eq.false'});} @override Future<ApiResult<GenderModel>> createGender(GenderDraft d)=>_api.post<GenderModel>(GendersEndpoint.collection,data:_json(d),options:Options(headers:{'Prefer':'return=representation'}),fromJsonList:_single); @override Future<ApiResult<GenderModel>> updateGender({required int id,required GenderDraft draft})=>_api.patch<GenderModel>(GendersEndpoint.collection,queryParameters:{'id':'eq.$id'},data:_json(draft),options:Options(headers:{'Prefer':'return=representation'}),fromJsonList:_single); @override Future<ApiResult<Unit>> deleteGender(int id)=>_api.delete(GendersEndpoint.collection,queryParameters:{'id':'eq.$id'}); @override Future<ApiResult<Unit>> setGenderActive({required int id,required bool isActive})=>_api.patch<Unit>(GendersEndpoint.collection,queryParameters:{'id':'eq.$id'},data:{'is_active':isActive},options:Options(headers:{'Prefer':'return=minimal'}),fromJson:(_)=>unit); String _order(GenderListQuery q){final terms=[for(final s in q.sorts)'${s.field.column}.${s.ascending?'asc':'desc}'];if(!q.sorts.any((s)=>s.field==GenderSortField.name))terms.add('name.asc');terms.add('id.asc');return terms.join(',');} GenderModel _single(List<dynamic> rows)=>PostgrestValue.single(rows,GenderModel.fromJson,what:'gender'); Map<String,dynamic> _json(GenderDraft d)=>{'name':d.name.trim(),'code':d.code.trim(),'sort_order':d.sortOrder,'is_active':d.isActive}; }